contract:
{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout",
    "input_channel": "stdin",
    "output_channel": "stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "isinstance(stdin, str) and 1 <= len(stdin) <= 1000",
      "description": "The input is a non-empty string with length not greater than 1000."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "is_valid_price(stdout)",
      "description": "The output is a valid price in the specified format."
    },
    {
      "id": "Q2",
      "expression": "stdout == calculate_total_price(stdin)",
      "description": "The output is the total price of all purchases in the bill."
    }
  ],
  "invariants": []
}

